def _v3_obs_pnl():
    p = os.path.join(config.KALSHI_DIR, "hourly_v3_pnl.jsonl")
    rows = []
    try:
        with open(p) as f:
            for line in f:
                try:
                    rows.append(json.loads(line))
                except Exception:
                    pass
    except Exception:
        pass
    return rows

